printf '\n--- resource-release hook ---\n' && sed -n '365,405p' /build/gcc-13.2.0/libstdc++-v3/libsupc++/eh_alloc.cc && printf '\n--- cache locale implementation ---\n' && sed -n '145,194p' /build/gcc-13.2.0/libstdc++-v3/include/bits/basic_ios.tcc && printf '\n--- patch user.cpp ---\n' && python3 - <<'PY'
from pathlib import Path
path = Path('/app/user.cpp')
text = path.read_text()
text = text.replace('#include "user.h"\n', '''#include "user.h"
#include <sstream>

// The statically linked libstdc++ retains its emergency exception pool.
// This library-provided hook releases it when the application is done.
namespace __gnu_cxx {
void __freeres() noexcept;
}
''')
text = text.replace('void user_init() {\n}', '''void user_init() {
    // Initialize the library's lazily registered locale facets before main.cpp
    // enables its custom heap. They live until static destruction, after that
    // heap has been destroyed, so they must be allocated on the normal heap.
    // Use numeric stream formatting to enter the linked library's facet code
    // even when the compiler's headers do not contain the in-house patch.
    std::ostringstream warmup;
    warmup << 0.0;
}''')
text = text.replace('void user_cleanup() {\n}', '''void user_cleanup() {
    // Valgrind cannot automatically release this pool in a static library.
    __gnu_cxx::__freeres();
}''')
path.write_text(text)
PY
printf '\n--- source diff ---\n' && diff -u /tmp/app-verification.ag1fF5/user.cpp.original /app/user.cpp; printf '\n--- verification ---\n'; /tmp/app-verification.ag1fF5/verify.sh
